import { ScalekitClient } from '@scalekit-sdk/node';
import * as fs from 'fs';

async function main() {
  const envUrl = process.env.SCALEKIT_ENV_URL;
  const clientId = process.env.SCALEKIT_CLIENT_ID;
  const clientSecret = process.env.SCALEKIT_CLIENT_SECRET;
  const runId = process.env.ZEALT_RUN_ID;

  if (!envUrl || !clientId || !clientSecret) {
    console.error('Missing required environment variables: SCALEKIT_ENV_URL, SCALEKIT_CLIENT_ID, SCALEKIT_CLIENT_SECRET');
    process.exit(1);
  }

  if (!runId) {
    console.error('Missing required environment variable: ZEALT_RUN_ID');
    process.exit(1);
  }

  const channelName = `agentkit-demo-${runId}`;
  const messageText = `scalekit-agentkit-ts ${runId}`;

  console.log(`Channel name: ${channelName}`);
  console.log(`Message text: ${messageText}`);

  const scalekit = new ScalekitClient(envUrl, clientId, clientSecret);

  const connector = 'slack-test';
  const identifier = 'zealt-user01';

  // Step 1: Create the channel (or get its ID if it already exists)
  console.log('Creating channel...');
  const createChannelResult = await scalekit.actions.executeTool({
    toolName: 'slack_create_channel',
    toolInput: {
      channel_name: channelName,
      is_private: false,
    },
    identifier,
    connector,
  });

  console.log('Create channel result keys:', Object.keys(createChannelResult));
  console.log('Create channel data:', JSON.stringify(createChannelResult.data, null, 2));

  const channelData = (createChannelResult.data as any)?.channel;
  let channelId: string;

  if (channelData && channelData.id) {
    channelId = channelData.id;
    console.log(`Created channel: ${channelName} (ID: ${channelId})`);
  } else {
    // Check if the error indicates the channel already exists
    const error = (createChannelResult.data as any)?.error;
    if (error === 'name_taken' || error === 'already_exists') {
      console.log('Channel already exists, searching for it...');
      const listResult = await scalekit.actions.executeTool({
        toolName: 'slack_list_channels',
        toolInput: {
          types: 'public_channel,private_channel',
          limit: 1000,
        },
        identifier,
        connector,
      });

      const channels = (listResult.data as any)?.channels || [];
      const foundChannel = channels.find((c: any) => c.name === channelName);

      if (!foundChannel) {
        console.error(`Could not find existing channel: ${channelName}`);
        process.exit(1);
      }
      channelId = foundChannel.id;
      console.log(`Found existing channel: ${channelName} (ID: ${channelId})`);
    } else {
      console.error('Failed to create channel:', JSON.stringify(createChannelResult.data));
      process.exit(1);
    }
  }

  // Step 2: Post message to the channel
  console.log('Posting message...');
  const postResult = await scalekit.actions.executeTool({
    toolName: 'slack_send_message',
    toolInput: {
      channel: channelId,
      text: messageText,
    },
    identifier,
    connector,
  });

  console.log('Post message result:', JSON.stringify(postResult.data, null, 2));

  const messageTs = (postResult.data as any)?.ts;
  if (!messageTs) {
    console.error('Failed to get message timestamp from response');
    process.exit(1);
  }

  // Write output.log
  const logContent = `Message TS: ${messageTs}\nChannel: ${channelName}\n`;
  fs.writeFileSync('/home/user/myproject/output.log', logContent);
  console.log('output.log written successfully');
  console.log(logContent);
}

main().catch((err) => {
  console.error('Error:', err);
  process.exit(1);
});

