  const error = (createChannelResult.data as any)?.error;

  if (channelData && channelData.id) {
    channelId = channelData.id;
    console.log(`Created channel: ${channelName} (ID: ${channelId})`);
  } else if (error === 'name_taken') {
    // Channel already exists, find it
    console.log('Channel already exists (name_taken), searching for it...');
  } else if (error === 'missing_scope') {
    // The OAuth token doesn't have channels:write scope. Try using the proxy API directly.
    console.log('AgentKit tool lacks channels:write scope. Trying proxy API...');
    try {
      const proxyResult = await scalekit.actions.request({
        connectionName: connector,
        identifier,
        path: '/api/conversations.create',
        method: 'POST',
        body: {
          name: channelName,
          is_private: false,
        },
      });
      console.log('Proxy create channel response:', JSON.stringify(proxyResult.data, null, 2));
      if (proxyResult.data?.ok && proxyResult.data?.channel?.id) {
        channelId = proxyResult.data.channel.id;
        console.log(`Created channel via proxy: ${channelName} (ID: ${channelId})`);
